// Module 4 \u2014 HTML & Web Development
// Rewritten for 17-year-old first-time ICT students at Amity Tashkent.
// Plain English, short sentences, Tashkent / Uzbekistan scenarios, no deep jargon.
// HTML code syntax appears in q/opts \u2014 always escape < and > as &lt; and &gt;
// Bloom's: Q1-Q2 Remember \u00b7 Q3-Q4 Understand \u00b7 Q5-Q7 Apply \u00b7 Q8 Analyze \u00b7
// Q9 Evaluate \u00b7 Q10 Create. Correct answer is NEVER the longest option.

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: World Wide Web ───
  1: [
    { q: "What is the World Wide Web, in simple words?", opts: ["A file type like .docx or .jpg that you save on your laptop when you download something", "The cables and wires that physically connect every single computer on the entire planet together", "A brand-name app made only by Google that shows websites on your phone and your computer", "A huge collection of web pages stored on computers around the world"], ans: 3, why: "The WWW is the set of web pages you visit with a browser (Chrome, Firefox). Cables are the internet, not the web. Chrome is one browser. The web is not a file type.", bloom: "remember" },
    { q: "Which of these is an example of a URL?", opts: ["A program file on your laptop like chrome.exe that you double-click to start the browser", "https://www.yandex.uz/news \u2014 a web address starting with a protocol and a domain name", "A random phone number that tells the internet where to send the web page you are asking for", "An IP address written as four numbers joined by dots, used only by email servers on the internet"], ans: 1, why: "A URL is a web address. It usually starts with https://, then the domain (yandex.uz), then maybe a path (/news). IP addresses exist, but a URL is the human-friendly version.", bloom: "remember" },
    { q: "Why is the internet NOT the same as the World Wide Web?", opts: ["Internet and web are the same \u2014 just two different words people use for exactly the same thing in practice", "The internet is only for emails and the web only for videos \u2014 they were built by two different companies", "The internet is the network (cables, Wi-Fi); the web is ONE thing you can do on it \u2014 visit pages", "The web came first, and the internet was added later to connect it to phones and modern smart devices"], ans: 2, why: "The internet is the global network of connected computers. The web is one service running on it \u2014 pages you visit with a browser. WhatsApp calls, email, and online games also use the internet but are NOT the web.", bloom: "understand" },
    { q: "Why does HTTPS (with the \u201cs\u201d) matter more than plain HTTP when you type a password?", opts: ["HTTPS pages load much faster on most phones and save a lot of your mobile data over time every month", "HTTPS looks nicer in the address bar and shows a little lock icon that makes users feel safer on the page", "HTTP was removed from the internet last year and only HTTPS still works on any modern browser today", "HTTPS scrambles your data on the way, so a stranger on the Wi-Fi can\u2019t read your password"], ans: 3, why: "Plain HTTP sends data as readable text \u2014 anyone on the same Wi-Fi could read it. HTTPS scrambles it so only the server can unscramble it. That\u2019s why login pages always use HTTPS.", bloom: "understand" },
    { q: "You see a URL <code>https://uzum.uz/phones</code>. Which part is the domain?", opts: ["https:// \u2014 the part at the very start that tells the browser it\u2019s a safe encrypted connection over the internet", "uzum.uz \u2014 the website name, with .uz meaning it belongs to Uzbekistan and is registered there as a domain", "/phones \u2014 the path that tells the server you want the phones page instead of the home page of that website", "The whole URL together is called the domain, including the https part and the slash after the .uz ending"], ans: 1, why: "The domain is the website name \u2014 uzum.uz here. .uz is the country ending for Uzbekistan. https:// is the protocol, and /phones is the path inside the site.", bloom: "apply" },
    { q: "Your friend in Tashkent asks which app they need to visit a website. What do you say?", opts: ["A web browser like Chrome, Firefox, or Edge \u2014 any of these can open web pages from any URL", "MS Word, because Word has a special tab that can load any website directly from within the document view", "Notepad, because it is small and fast and already installed on every single Windows laptop out of the box", "Telegram, because Telegram is the most popular messaging app in Uzbekistan among students and adults"], ans: 0, why: "A web browser (Chrome, Firefox, Edge, Safari) is the app that loads and shows websites. Word is for documents. Notepad is for plain text. Telegram is a chat app, not a web browser.", bloom: "apply" },
    { q: "You want to buy a phone on Uzum. Which URL would you type into the browser?", opts: ["uzum.docx — a Word document file name that acts like a shortcut to the shop’s home page when opened", "uzum://buy.phone — the colon-slash pattern is how you open shopping sites from a browser’s address bar", "www@uzum.uz — the at sign is used like in emails to point the browser at the Uzum shop’s main web page", "https://uzum.uz — a normal secure URL using https, the Uzum domain name, and the .uz country ending"], ans: 3, why: "A URL is https:// + domain + maybe a path. https://uzum.uz works. .docx is a Word file. The @ is for email addresses. uzum://buy.phone isn\u2019t a real URL.", bloom: "apply" },
    { q: "A student\u2019s page won\u2019t load. They see \u201cNot Secure\u201d in the address bar. What is most likely the reason?", opts: ["The student\u2019s browser has a serious bug and every other user in the world is seeing the same warning too today", "The whole internet has been disabled by the Uzbek government, so no site anywhere in the country will load right", "The site uses plain http:// without the s, so the browser warns the user that the page is not safely encrypted", "The Wi-Fi signal is weak and the browser gave up loading the page after waiting too long for a first response"], ans: 2, why: "A \u201cNot Secure\u201d label means the site is on http:// (no encryption). The page may still load \u2014 the warning is about safety, not the connection. Don\u2019t type passwords on non-secure pages.", bloom: "analyze" },
    { q: "Your cousin says: \u201cI don\u2019t need a browser \u2014 I just use Instagram, so I don\u2019t really use the web.\u201d Is this true?", opts: ["Yes \u2014 apps and the web are completely separate, and using only apps means you never touch the web at all anymore these days", "Not quite \u2014 apps still load content from web servers over URLs; Instagram just hides the bar", "Yes \u2014 modern smartphones don\u2019t use the web anymore at all, so browser apps will be removed from phones soon by every maker", "No \u2014 Instagram is actually just a browser with a different-looking icon on the home screen of every mobile phone in the world today"], ans: 1, why: "Apps LOOK different from browsers, but they still fetch content from web servers in the background \u2014 same URLs, same protocols. The web isn't dead, it's just often hidden behind an app's interface.", bloom: "evaluate" },
    { q: "Your grandmother asks: \u201cHow does the web work?\u201d Design a simple 4-step answer she\u2019ll understand.", opts: ["(1) Type a web address. (2) Browser asks a server. (3) Server sends the page back. (4) Browser shows it to you.", "Start from the deep physics of fibre-optic signals, then explain routing, then TCP handshakes, then browsers in full", "Tell her the web is magic and works by itself without any computers or servers or other kinds of hidden machines", "Just say \u201cI don\u2019t know\u201d because the web is way too complex for anyone without a computer science degree to understand"], ans: 0, why: "A 4-step explanation your grandmother can follow: you type an address, browser asks a server, server sends the page, browser paints it. No jargon needed. \u201cIt\u2019s magic\u201d or \u201cI don\u2019t know\u201d aren\u2019t answers.", bloom: "create" },
  ],

  // ─── Topic 2: HTML & Basic Tags ───
  2: [
    { q: "What does HTML stand for?", opts: ["HyperText Markup Language \u2014 the language used to build the structure of web pages", "Home Tools Made Longer, which is a joke expansion that nobody really uses in modern coding today", "Hyper Tool for Media Logins, a phrase made up by the first internet designers back in the 1990s", "High-Tech Micro-Language, a phrase invented at Microsoft when Internet Explorer first came out on the market"], ans: 0, why: "HTML = HyperText Markup Language. \u201cHypertext\u201d = text that links to other text. \u201cMarkup\u201d = adding tags around content. The rest are made up.", bloom: "remember" },
    { q: "Which tag is the biggest heading on a web page?", opts: ["&lt;h6&gt; \u2014 which gives the biggest, boldest heading because the number six is the largest single-digit option here", "&lt;big&gt; \u2014 a tag that simply makes the text size much larger than the other tags, no matter where you put it", "&lt;h1&gt; \u2014 the largest heading, usually used once at the top of the page for the main title of that page", "&lt;title&gt; \u2014 the correct tag for the biggest visible heading at the top of the visible part of the web page"], ans: 2, why: "<h1> is the biggest heading; <h6> is the smallest. <title> sets the browser TAB title (not visible on the page). <big> exists in old HTML but isn\u2019t the standard heading tag.", bloom: "remember" },
    { q: "Why does an HTML page need both a <code>&lt;head&gt;</code> AND a <code>&lt;body&gt;</code>?", opts: ["Every file needs exactly two parts by an ancient rule, and HTML copied this rule directly from the Microsoft Word format", "The head is where JavaScript lives, and the body is where images live — nothing else is allowed in either section", "Because head and body are identical tags and using both guarantees the page renders on any old browser you open", "The head holds info about the page (title, settings); the body holds everything the visitor actually sees"], ans: 3, why: "<head> holds behind-the-scenes info \u2014 the tab title, character set, styles. <body> holds what appears on the page. Two rooms, two jobs. Text, images, lists, links \u2014 body.", bloom: "understand" },
    { q: "Why do we need <code>&lt;!DOCTYPE html&gt;</code> at the very top of every page?", opts: ["It just looks more professional and is the line that makes the page print nicely on most modern home printers today", "Without it the page won\u2019t load at all, and every browser in the world will refuse to display it until it\u2019s added", "It tells the browser \u201cthis is modern HTML5\u201d so the page renders using today\u2019s rules, not weird old ones", "It\u2019s the line that adds the page\u2019s tab title, the favicon, and the scroll bars on the side of the screen"], ans: 2, why: "<!DOCTYPE html> tells the browser to use modern HTML5 rules. Without it, browsers fall into \u201cquirks mode\u201d \u2014 old 1990s behaviour that can break your layout. Fifteen characters, big win.", bloom: "understand" },
    { q: "You want the browser tab to say \u201cMy Portfolio.\u201d Which tag do you use?", opts: ["Put the text <h1>My Portfolio</h1> in the body \u2014 the main heading of the page also sets the browser tab title", "Put <title>My Portfolio</title> inside the <head> \u2014 this tag controls the text shown on the browser tab", "Use <tab>My Portfolio</tab> \u2014 the name of the tag matches the word tab, so the browser uses it for the tab", "Write <p>My Portfolio</p> at the very top of the page and the browser will copy that into the tab by default"], ans: 1, why: "The browser tab is controlled by <title> inside <head>. <h1> is a big heading that shows ON the page itself. <tab> isn\u2019t a real HTML tag. A <p> paragraph doesn\u2019t set the tab.", bloom: "apply" },
    { q: "You want a big title saying \u201cTashkent Travel Guide\u201d at the top of your page. Which tag is right?", opts: ["<h1>Tashkent Travel Guide</h1> \u2014 the largest heading tag, used once for the main title at the top of the page", "<title>Tashkent Travel Guide</title>, but place it directly inside the body so that the heading appears on screen", "<p><b>Tashkent Travel Guide</b></p>, so the line is shown as a paragraph with bold text near the top of the page", "<head>Tashkent Travel Guide</head> \u2014 the head tag is the correct choice because it holds the top heading line"], ans: 0, why: "For a visible big title, <h1> is the right choice. <title> is for the tab. Bold paragraphs work visually but aren\u2019t proper headings (and SEO / screen readers care). <head> isn\u2019t for visible content.", bloom: "apply" },
    { q: "You open Notepad and paste HTML code. What must you save the file as?", opts: ["Save as a .txt file \u2014 Notepad\u2019s default file type works perfectly fine for any HTML code you write into it", "Save as .html \u2014 otherwise the browser reads it as plain text and shows the tags on screen instead of the page", "Save as .docx so MS Word can open it and display the HTML tags as formatted output in a nice document view", "Save as .jpg because HTML files are a kind of image format that browsers display like any photo on the internet"], ans: 1, why: "The .html ending tells the computer \u201cthis is a web page.\u201d Double-click and it opens in a browser. A .txt file opens as plain text and shows the tags. .docx is Word, .jpg is an image.", bloom: "apply" },
    { q: "A student\u2019s page shows the words <code>&lt;h1&gt;Hello&lt;/h1&gt;</code> on the screen instead of the big heading \u201cHello.\u201d What went wrong?", opts: ["The student forgot to include <!DOCTYPE html> at the top, so the browser is refusing to render the page correctly", "The file was saved as .txt instead of .html, so the browser treats the tags as plain characters, not HTML", "The student\u2019s Notepad application is broken and needs to be reinstalled from the official Microsoft website first", "The browser is only able to display images and cannot handle text content of any kind, including HTML web pages"], ans: 1, why: "If the tags show up literally on the page, the browser is reading the file as plain text \u2014 almost always because the file was saved as .txt instead of .html. Resave as me.html, reopen.", bloom: "analyze" },
    { q: "Your classmate says: \u201cI don\u2019t need <code>&lt;!DOCTYPE html&gt;</code> \u2014 my page still works in Chrome.\u201d Evaluate.", opts: ["Correct \u2014 DOCTYPE is optional these days and modern browsers happily ignore it everywhere without any real issues", "Correct \u2014 it slows down the page and should always be removed to make every single web page load slightly faster", "Not a great idea \u2014 without DOCTYPE, browsers can slip into old \u201cquirks mode\u201d and some layouts break", "Correct \u2014 DOCTYPE is only for very old pages from the 1990s and nobody on the modern web ever really needs it"], ans: 2, why: "Without DOCTYPE, browsers drop into \u201cquirks mode\u201d \u2014 old 1990s behaviour. Your page might look fine today but break tomorrow in subtle ways. Fifteen characters of safety is worth it.", bloom: "evaluate" },
    { q: "Design the full skeleton of a page with the tab title \u201cMy Amity Page\u201d and a heading \u201cWelcome.\u201d Which option is correct?", opts: ["Paste the words into MS Word, save as a .docx file, and then rename it to .html so that the browser can open it", "Only the text Welcome, with no tags at all — because modern browsers can figure out the structure of pages on their own now", "A single <h1>My Amity Page Welcome</h1> tag written directly in the file, with no html, head, or body tags anywhere at all", "<!DOCTYPE html>, then <html>, with <head> holding <title>My Amity Page</title>, and <body> holding <h1>Welcome</h1>"], ans: 3, why: "Full skeleton: <!DOCTYPE html> \u2192 <html> \u2192 <head><title>...</title></head> \u2192 <body><h1>...</h1></body>. Tab title goes in <head>, visible heading in <body>. Renaming a .docx file doesn\u2019t work.", bloom: "create" },
  ],

  // ─── Topic 3: HTML Elements ───
  3: [
    { q: "What is an HTML element?", opts: ["Just the opening tag on its own, like <p> or <h1>, without any of the content or the closing tag included", "The opening tag + the content in the middle + the closing tag, all together as ONE complete unit", "Only the content between the tags, but never the tags themselves, since the tags are just invisible hints", "Any text on the page, whether it is inside tags, outside tags, or written in a random place in the whole file"], ans: 1, why: "An element is the full package: opening tag, content, closing tag. <p>Hello</p> is an element. Just <p> alone is a tag \u2014 one piece of the element.", bloom: "remember" },
    { q: "Which of these is a self-closing tag (no closing tag needed)?", opts: ["<p> \u2014 a paragraph tag that holds normal text on the page and always needs a closing tag to be written", "<h1> \u2014 the biggest heading tag, which also needs a closing tag to mark where the heading finally ends", "<br> \u2014 a line-break tag that has no content and stands alone, so it doesn\u2019t need a closing tag", "<div> \u2014 a general block container for grouping other elements and needs both opening and closing tags"], ans: 2, why: "<br> (line break) stands alone \u2014 no content, no closing tag. <p>, <h1>, <div> all need closing tags. Other self-closing tags: <hr> (horizontal line) and <img> (image).", bloom: "remember" },
    { q: "Why does the closing tag have a forward slash (like <code>&lt;/p&gt;</code>)?", opts: ["The slash is just decorative and the browser actually ignores it completely whenever it loads any HTML page", "It\u2019s the signal that tells the browser \u201cthis element ends HERE\u201d \u2014 without it, the browser keeps going", "The slash is there because HTML was copied from URLs, which always use forward slashes in their paths", "The slash makes the text slightly italic, so the browser can visually tell the tags apart in View Source"], ans: 1, why: "The slash says \u201cend of this element.\u201d Without it, the browser thinks the element is still open and keeps applying its style to everything after. <h1> without </h1> turns the whole page into one giant heading.", bloom: "understand" },
    { q: "What\u2019s the difference between a \u201ctag\u201d and an \u201celement\u201d?", opts: ["Tag and element mean the same thing and developers just use two different words for the exact same idea in HTML", "Element is old-style HTML and tag is the modern HTML5 replacement used in every new website made today", "Tag is one piece (opening or closing); element is the whole thing \u2014 opening tag, content, closing tag", "Tag only exists inside the head section, and element only exists inside the body section of an HTML document"], ans: 2, why: "Tag = one piece (<p> or </p>). Element = the whole thing (<p>Hello</p>). Tags are like bread slices; an element is the whole sandwich.", bloom: "understand" },
    { q: "You want to show a paragraph that says \u201cI live in Tashkent.\u201d Which line is right?", opts: ["I live in Tashkent. — you don’t need any tags because the browser will automatically format the sentence for you", "&lt;p&gt;I live in Tashkent. — opening tag only, no closing tag, because paragraphs don’t actually need to be closed in HTML", "&lt;paragraph&gt;I live in Tashkent.&lt;/paragraph&gt; — use the full word paragraph so it is easier to read in the code", "&lt;p&gt;I live in Tashkent.&lt;/p&gt; — a paragraph tag wrapping the sentence, with a proper closing tag at the end"], ans: 3, why: "A paragraph is <p>...</p>. The full word \u201cparagraph\u201d isn\u2019t a real tag. Skipping the closing </p> can break layout. No tags = the browser just shows one line of plain text.", bloom: "apply" },
    { q: "You want a line break (go to a new line) inside a paragraph. Which tag do you use?", opts: ["&lt;br&gt; \u2014 a self-closing line-break tag that forces the next text onto a new line below, with no closing tag needed", "&lt;newline&gt; \u2014 a simple self-explanatory tag that tells the browser to start the next piece of text on a fresh line", "&lt;n&gt; \u2014 the HTML shortcut tag that creates a new line inside a paragraph without requiring any closing tag at all", "&lt;enter&gt; \u2014 a tag that mimics the Enter key on a keyboard, adding a blank line wherever it appears in the source"], ans: 0, why: "<br> is the line-break tag. It\u2019s self-closing (no </br> needed). <newline>, <n>, and <enter> are not real HTML. <br> is extremely common for addresses or poems.", bloom: "apply" },
    { q: "You want a horizontal line (divider) between two sections of your page. Which tag?", opts: ["&lt;line&gt; \u2014 the obvious tag name, which draws a flat line across the whole width of the page with no closing tag", "&lt;hr&gt; \u2014 horizontal rule, a self-closing tag that draws a thin line across the page to separate two sections", "&lt;divider&gt; \u2014 a newer HTML5 tag that was added specifically to create horizontal dividers between page sections", "&lt;break&gt; \u2014 a tag that works like pressing Enter three times and leaves empty space to visually separate two sections"], ans: 1, why: "<hr> = horizontal rule. A thin grey line across the page. Self-closing. <line>, <divider>, and <break> are not real HTML tags.", bloom: "apply" },
    { q: "A student writes <code>&lt;h1&gt;My Page</code> (no closing tag) and the whole rest of the page shows as a giant heading. What went wrong?", opts: ["The <h1> tag is only supposed to be used with uppercase H1, so the lowercase version broke the whole page right away", "The browser is broken and will only work after the student updates Chrome to the newest version from the website", "Notepad corrupted the file when the student pressed save, and now every heading tag in it turned into an h1 one", "Without the closing </h1>, the browser keeps treating everything as heading until it finally finds an h1 close"], ans: 3, why: "No closing </h1> means the browser keeps \u201che heading\u201d open \u2014 so every word after looks like a giant heading. Add </h1> at the end of the heading text to fix it. Tags come in pairs.", bloom: "analyze" },
    { q: "A coder says: \u201cWriting </img> for every image is cleaner, so I always do it.\u201d Is this a good habit?", opts: ["Yes \u2014 every tag needs a closing tag by rule and every modern coder in every company closes img this way every day", "Yes \u2014 it makes the HTML file bigger and clearer to read, which helps teachers grade your school HTML assignments fast", "Not quite \u2014 <img> is self-closing by design, so </img> is wrong and causes unexpected rendering on some browsers", "Yes \u2014 it doesn\u2019t matter at all, because browsers treat self-closing and normal closing tags in the exact same way in practice"], ans: 2, why: "Self-closing tags (<img>, <br>, <hr>) don\u2019t take a closing tag. Adding </img> isn\u2019t standard HTML and can confuse some tools. \u201cCleaner\u201d isn\u2019t the same as \u201ccorrect\u201d \u2014 follow the real rule.", bloom: "evaluate" },
    { q: "Design a paragraph with a broken line in the middle: \u201cI live in Tashkent. I study at Amity.\u201d Second sentence on a new line. Which is right?", opts: ["&lt;p&gt;I live in Tashkent.&lt;br&gt;I study at Amity.&lt;/p&gt; \u2014 one paragraph with a line break between the two sentences", "&lt;p&gt;I live in Tashkent.&lt;/p&gt;&lt;p&gt;I study at Amity.&lt;/p&gt; which also works, but that\u2019s TWO paragraphs, not a single one with a line break", "Skip the tags and press Enter twice in Notepad, because the browser will also respect the line breaks the student puts in the source file", "Use a big <br><br><br><br> in the middle of the sentence to create a big gap between the two lines of the same paragraph"], ans: 0, why: "To keep ONE paragraph with a new line inside, use <p>sentence one.<br>sentence two.</p>. Two <p> elements = two paragraphs. Pressing Enter in Notepad does nothing in HTML \u2014 browsers ignore raw line breaks.", bloom: "create" },
  ],

  // ─── Topic 4: HTML Attributes ───
  4: [
    { q: "Where do attributes go in an HTML tag?", opts: ["Inside the closing tag, as name=\"value\" pairs separated by a space between each one in the order you wrote them", "Inside the opening tag, as name=\"value\" pairs giving extra info about the element", "In the content, between the opening and closing tags, where the visible text of the element normally lives", "Anywhere in the file, as long as they are wrapped in quotes \u2014 browsers will find them and link them up"], ans: 1, why: "Attributes go in the opening tag: <img src=\"photo.jpg\" width=\"200\">. Never in the closing tag. Never between tags. Always as name=\"value\" pairs.", bloom: "remember" },
    { q: "Which attribute tells an <code>&lt;img&gt;</code> which file to load?", opts: ["file \u2014 a simple name that clearly tells the browser to load a file from the same folder as the HTML page", "source \u2014 the full long English word version of the attribute, accepted by all the modern major browsers today", "src \u2014 short for \u201csource,\u201d pointing to the image file or the URL the browser should display", "image \u2014 the obvious choice, because the name matches the tag itself and describes exactly what it holds"], ans: 2, why: "src = \u201csource\u201d \u2014 the path or URL of the image. <img src=\"cat.jpg\"> or <img src=\"https://site.uz/logo.png\">. The others aren\u2019t real HTML attributes.", bloom: "remember" },
    { q: "Why must attribute values always be inside quotes, like <code>width=\"200\"</code>?", opts: ["Quotes make the HTML look cleaner but aren\u2019t really needed, and the browser still works fine without them every time", "Quotes tell the browser exactly where the value starts and ends \u2014 especially important when a value has spaces in it", "Quotes are only used for values written in English \u2014 numbers alone, like 200, never need any quotes around them at all", "Quotes mean the value is encrypted, and without them the attribute data could be read by strangers over the Wi-Fi"], ans: 1, why: "Quotes mark the boundaries of the value. Simple values (width=200) often work, but values with spaces (alt=\"Me in Samarkand\") break without quotes. Just always use quotes \u2014 no exceptions.", bloom: "understand" },
    { q: "Why is the <code>alt</code> attribute on an image important?", opts: ["It sets the image\u2019s border colour and has no other effect on how the image appears or behaves on the page", "It shows as text when the image fails to load, and is read aloud by screen readers for blind users", "It makes the page load much faster by telling the browser to skip downloading the image file itself at load time", "It automatically translates the image text into the user\u2019s native language so they can understand the content"], ans: 1, why: "alt = alternative text. If the image doesn\u2019t load (broken src, slow Wi-Fi), the alt text shows in its place. Screen readers read it aloud for blind users. Always include it \u2014 easy accessibility win.", bloom: "understand" },
    { q: "You want a photo of Registan Square on your page, 300 pixels wide, with backup text. Which tag is right?", opts: ["&lt;image&gt;&lt;src&gt;registan.jpg&lt;/src&gt;&lt;width&gt;300&lt;/width&gt;&lt;/image&gt; — nested tags where each attribute is its own element", "&lt;img&gt;registan.jpg 300 Registan Square&lt;/img&gt; — put the file name and the width and the alt text between the tags", "&lt;photo name=\"registan.jpg\" size=\"300\"&gt; — a photo tag with a name attribute for the file and a size attribute for width in pixels", "&lt;img src=\"registan.jpg\" width=\"300\" alt=\"Registan Square\"&gt; — all three attributes inside one self-closing img tag"], ans: 3, why: "All attributes go inside the opening <img> tag, separated by spaces. <img> is self-closing. <photo> and <image> (as a tag) aren\u2019t real HTML. Attributes are never nested as child tags.", bloom: "apply" },
    { q: "You want a link to <code>yandex.uz</code> that says \u201cSearch\u201d. Which line is right?", opts: ["&lt;a href=\"https://yandex.uz\"&gt;Search&lt;/a&gt; \u2014 an anchor tag with the href pointing to Yandex and the visible word Search", "&lt;a&gt;Search&lt;/a&gt; goes to yandex.uz \u2014 the browser is clever enough to find the destination from the word Search in the link", "&lt;link to=\"yandex.uz\"&gt;Search&lt;/link&gt; \u2014 the link tag is the modern standard for creating links on any web page these days", "&lt;a url=\"yandex.uz\"&gt;Search&lt;/a&gt; \u2014 use the url attribute so the browser clearly sees the destination of this link"], ans: 0, why: "Links use <a href=\"url\">visible text</a>. The attribute is href, not url or to. <link> is a real tag but it\u2019s for the <head> (stylesheets), not clickable links.", bloom: "apply" },
    { q: "You want your photo to be 250 pixels wide. Which line is right?", opts: ["&lt;img src=\"me.jpg\" size=\"250\"&gt; \u2014 the size attribute controls how wide the image should appear on the finished web page", "&lt;img src=\"me.jpg\" pixels=\"250\"&gt; \u2014 use pixels directly so the browser understands the image should be 250 pixels wide", "&lt;img src=\"me.jpg\" width=\"250\"&gt; \u2014 width is the correct attribute, taking a number in pixels", "&lt;img src=\"me.jpg\"&gt;&lt;width&gt;250&lt;/width&gt; \u2014 put the width tag right after the image tag to set its size"], ans: 2, why: "The correct attribute is width. <img src=\"me.jpg\" width=\"250\"> makes the image 250 pixels wide. size and pixels aren\u2019t real HTML attributes. Attributes go inside the same tag, not as child tags.", bloom: "apply" },
    { q: "A classmate\u2019s photo shows a broken-image icon instead of the photo. What\u2019s the most likely reason?", opts: ["The photo is too big in file size, so the browser refused to load it and shows the broken-icon as a safety warning", "The alt attribute is missing, and without alt the browser can’t find any photo file to put into the image frame", "The image file is fine, but the closing </img> tag was missing, so the browser refused to show the image at all", "The src attribute points to a file that doesn’t exist — wrong name, wrong folder, or not uploaded yet"], ans: 3, why: "A broken-image icon means the browser couldn\u2019t find the file in src. Check the file name spelling, the folder, and whether the photo is actually there. Missing alt just means no backup text \u2014 the file itself is a separate problem.", bloom: "analyze" },
    { q: "Your friend says: \u201cI never add <code>alt</code> to my images \u2014 they slow the page down.\u201d Evaluate.", opts: ["Correct \u2014 alt makes every image file bigger on disk, which slows pages down on slow connections and should be avoided", "Correct \u2014 only blind people use alt, and most websites don\u2019t need to worry about blind users at all these days", "Not a good idea \u2014 alt is tiny text, doesn\u2019t slow anything, and it helps when the image itself fails to load too", "Correct \u2014 modern browsers ignore alt entirely because CSS replaces it with better tooltips that the designer adds"], ans: 2, why: "alt is just a few words of text in the tag \u2014 it doesn\u2019t slow the page. It shows when the image fails, it\u2019s read aloud for blind users, and it helps search engines understand the image. No downside. Always include alt.", bloom: "evaluate" },
    { q: "Design an <code>&lt;img&gt;</code> tag for a photo of Chorsu Bazaar that\u2019s 400 pixels wide and has good backup text.", opts: ["&lt;img src=\"chorsu.jpg\" width=\"400\" alt=\"Chorsu Bazaar dome in Tashkent\"&gt; \u2014 src for file, width for size, alt for backup text", "&lt;img&gt; \u2014 an image tag on its own, because the browser can auto-detect which photo and how big just from its surroundings", "&lt;img name=\"chorsu.jpg\"&gt; \u2014 use the name attribute to pick the file and let the browser decide the size on its own", "&lt;image file=\"chorsu.jpg\" size=\"400\"&gt;Chorsu Bazaar&lt;/image&gt; \u2014 a photo tag with descriptive attributes and content between it", ], ans: 0, why: "A good <img> has src (file), width (size), and alt (backup text) \u2014 all inside the single self-closing tag. <image>, name, and file aren\u2019t real HTML. The browser can\u2019t guess which file to load.", bloom: "create" },
  ],

  // ─── Topic 5: HTML Comments ───
  5: [
    { q: "Which is the correct syntax for an HTML comment?", opts: ["// comment \u2014 a forward-slash comment style copied from the JavaScript programming language and widely used on the web", "# comment \u2014 a hash-based comment style that mirrors the kind of comments used in many shell scripts and Python", "&lt;!-- comment --&gt; \u2014 start with less-than-exclamation-dash-dash, end with dash-dash-greater-than", "/* comment */ \u2014 a slash-star comment style that is copied from the CSS language and is used in old HTML files"], ans: 2, why: "HTML comments are <!-- ... -->. // is for JavaScript. # is for shell / Python. /* */ is for CSS. Each language has its own comment style.", bloom: "remember" },
    { q: "What does the browser do with an HTML comment?", opts: ["Shows it to the user in a small grey box next to the rest of the page so other coders can read and understand the notes", "Turns the comment into a pop-up box that appears the moment the user clicks anywhere on the page itself", "Reads the comment aloud using the computer’s speakers whenever a user loads the page for the first time", "Ignores it completely — the comment stays in the file for humans but never appears on the page"], ans: 3, why: "Browsers skip comments when rendering. They\u2019re invisible to visitors. They stay in the source file so you and your teammates can read notes \u2014 but nothing shows on the page itself.", bloom: "remember" },
    { q: "Why do we use comments in HTML, if the browser just ignores them?", opts: ["To leave notes for YOU and other coders — explain what code does, mark sections, leave to-do reminders", "They protect private info by hiding it inside the code where only logged-in users can actually read the contents", "They make the page load faster by telling the browser which parts of the code are safe to skip over when loading", "To automatically boost the site’s Google ranking by adding keyword-rich notes that the search engine picks up"], ans: 0, why: "Comments exist for humans: explain what a section does, mark parts of the page, leave \u201cTODO: fix this\u201d notes. They don\u2019t speed the page, don\u2019t hide secrets (anyone can view source), don\u2019t affect SEO.", bloom: "understand" },
    { q: "Are comments really \u201chidden\u201d? Can anyone visiting the page see them?", opts: ["Yes, comments are fully encrypted and nobody visiting the page can read them, even if they look at the source code", "Comments are stored in a separate secret file on the server and never sent to anyone visiting the web page at all", "Yes, only the page author can see their own comments; the browser automatically strips them out for all visitors", "Not really — right-click → View Page Source shows all comments. They’re invisible on the page but not in the file"], ans: 3, why: "Comments are NOT rendered on the page, but the whole HTML file gets sent to the browser. Anyone can right-click \u2192 View Page Source and see every comment. Never put passwords or secrets in them.", bloom: "understand" },
    { q: "You want to temporarily hide a broken <code>&lt;img&gt;</code> tag without deleting it. What\u2019s the fastest way?", opts: ["Retype the img tag in a different font colour, so the browser knows it is temporarily disabled during your testing session today", "Wrap the &lt;img&gt; in &lt;!-- ... --&gt; so the browser ignores it", "Delete the whole line and then retype it later when you have fixed the file path so you can just start fresh each time you do this", "Save the img tag in a separate text file on your desktop and paste it back in when the image file is available again for your page"], ans: 1, why: "Commenting out (<!-- ... -->) hides code from the browser without deleting it. Great for debugging \u2014 take the markers off later to bring it back. Deleting means you have to retype. Saving to another file is slow.", bloom: "apply" },
    { q: "You\u2019re building a long HTML page and want to label the different sections. What\u2019s a good way to use comments?", opts: ["Add a short comment above each section (Header, Menu, Contact) to guide the reader at a glance", "Skip comments entirely and rely on the order of the tags for anyone who reads the file later on in the school year across terms", "Put every comment at the end of the file in one big block so readers know to scroll down to find all of them together on the page", "Write comments inside the body text so that visitors reading the page can see them and know what each section actually does for them"], ans: 0, why: "Section-label comments (like <!-- Menu table -->) help you and teammates scan a long file fast. Comments at the end of the file don't help. Comments inside body text would still be hidden from visitors anyway.", bloom: "apply" },
    { q: "In your exam, you\u2019re told to add a table to your HTML answer. Why should you also add a comment above it?", opts: ["A comment changes the table\u2019s border colour and makes the exam grading look better to the examiner reading your code", "It shows the examiner you understand the structure \u2014 &lt;!-- Subjects table --&gt; earns you easy clarity marks", "Without a comment, the table will not load in the browser and the examiner won\u2019t see your answer on screen at all", "The comment makes the table centre itself automatically on the page, which makes the whole answer look more polished"], ans: 1, why: "Teachers love seeing <!-- Table --> above your table. It shows you planned your answer and understand what each part does. No visual effect, but exam markers give clarity points for well-commented code.", bloom: "apply" },
    { q: "A student wrote <code>&lt;!-- My email password is 1234 --&gt;</code> in their HTML file. Why is this dangerous?", opts: ["Comments slow the page down a lot, so a long comment about a password will cause the page to time out in Chrome", "Anyone can right-click \u2192 View Page Source and read the comment \u2014 the password is fully visible to any visitor", "The browser will try to log the user in using the password in the comment, causing every visitor to be logged in as that student", "Comments are stored on the server forever and the school admin will receive an alert whenever the comment is written or saved"], ans: 1, why: "Comments are in the source code, which anyone can view with right-click \u2192 View Page Source. A password in a comment = public password. Never put secrets in HTML \u2014 comments or otherwise.", bloom: "analyze" },
    { q: "A friend says: \u201cComments are pointless \u2014 I can remember what my code does.\u201d Evaluate.", opts: ["Correct \u2014 comments make the HTML file bigger which always slows the page down for users on slow mobile connections", "Correct \u2014 good coders don\u2019t need to comment because their code is clear on its own, and comments are just extra noise", "Not quite \u2014 YOU might remember today, but teammates and future-you (next month) often won\u2019t, so comments help everyone", "Correct \u2014 comments confuse the browser and make the page render in a different order than what the student wrote originally"], ans: 2, why: "You might remember your code today. Next month, after 10 other projects, you won\u2019t. A teammate opening your file never remembered in the first place. Comments are cheap insurance \u2014 don\u2019t skip them.", bloom: "evaluate" },
    { q: "Design a good set of comments for a homework HTML page with a heading, a table, a list, and a link.", opts: ["One huge comment at the very top of the file that says \u201cThis is my homework page\u201d and nothing else for any section of the whole document in any place at all", "No comments at all, because the teacher can see the tags and already understand the structure without any comment help being needed anywhere on the whole finished page", "Short &lt;!-- ... --&gt; labels above each section: Heading, Table, List, Link \u2014 one short comment per part", "A long essay as a comment at the end explaining every single tag you used and why you chose it instead of another one, with extra notes on every choice for clarity"], ans: 2, why: "Short label comments above each section (<!-- Heading -->, <!-- Subjects table -->, <!-- Hobbies list -->, <!-- Link -->) make the code scannable and show the teacher you understand your structure. A single giant top comment is less useful \u2014 readers want the label RIGHT above the thing it describes.", bloom: "create" },
  ],

  // ─── Topic 6: HTML Formatting ───
  6: [
    { q: "Which tag makes text <strong>bold</strong>?", opts: ["&lt;bold&gt; — the full English word as the tag name, which is the most obvious and commonly used bold tag in HTML", "&lt;heavy&gt; — a tag that makes the text appear with a heavier stroke and darker colour than the rest of the text", "&lt;strong-text&gt; — a compound tag that is used for bold formatting in modern web development practices today", "&lt;b&gt; — a short one-letter tag that wraps text to make it appear in bold on the web page"], ans: 3, why: "The bold tag is <b>. The HTML5 standard also accepts <strong> for the same effect (plus it adds a hint of importance for screen readers). <bold>, <strong-text>, <heavy> aren\u2019t real tags.", bloom: "remember" },
    { q: "Which tag makes text look like a yellow highlighter?", opts: ["&lt;highlight&gt; \u2014 an obvious English tag name that wraps any text with a bright yellow background on the finished page", "&lt;yellow&gt; \u2014 a simple tag that gives any text a yellow background, just like a physical highlighter pen would do", "&lt;mark&gt; \u2014 wraps text in a yellow background, like a school highlighter pen", "&lt;pen&gt; \u2014 a tag that applies the effect of a highlighter pen to the text inside it with just a single pair of tags"], ans: 2, why: "<mark> gives text a yellow background, like a highlighter. <highlight>, <yellow>, <pen> aren\u2019t real HTML tags. <mark> is short, easy to remember, and in the real HTML5 spec.", bloom: "remember" },
    { q: "What\u2019s the difference between <code>&lt;b&gt;</code> and <code>&lt;strong&gt;</code>?", opts: ["&lt;b&gt; just makes text look bold; &lt;strong&gt; also adds importance, so screen readers emphasise it", "They do exactly the same thing and there is absolutely no difference between them in any way on any modern browser", "&lt;b&gt; is an old tag from the 1990s that no longer works in any modern browser, and only strong still works today", "&lt;strong&gt; only works in combination with CSS, so without CSS it has no effect and the text stays plain on the page"], ans: 0, why: "Both make text look bold. <strong> also tells screen readers \u201cthis is important,\u201d so they can emphasise it. Same pixels, extra meaning. For a school project, <b> is fine; <strong> is slightly better.", bloom: "understand" },
    { q: "If you want BOTH bold AND italic, how do you write it?", opts: ["&lt;b-and-i&gt;text&lt;/b-and-i&gt; — a combined tag for applying bold and italic in a single step to a piece of text", "&lt;bold&gt;italic text&lt;/bold&gt; — the bold tag is enough because italic is automatically applied inside any bold wrapper", "You can’t — HTML does not allow combining bold and italic formatting at the same time inside one element anywhere", "Nest the tags: &lt;b&gt;&lt;i&gt;text&lt;/i&gt;&lt;/b&gt; — open both, then close them in the opposite order"], ans: 3, why: "Nest the tags: <b><i>text</i></b>. Open both, close in reverse order (last opened = first closed). There\u2019s no <b-and-i> tag, and HTML fully allows combining formatting.", bloom: "understand" },
    { q: "You\u2019re writing about your favourite dish. You want the word \u201cplov\u201d in italic. Which is right?", opts: ["&lt;p&gt;My favourite food is &lt;i&gt;plov&lt;/i&gt;.&lt;/p&gt; \u2014 wrap the single word plov with the italic tag inside the paragraph", "&lt;p&gt;My favourite food is plov.&lt;/p&gt; with no formatting \u2014 italics are added by the browser automatically for any food word", "&lt;i&gt;My favourite food is plov.&lt;/i&gt; \u2014 wrap the whole sentence, because italic tags must always span the full sentence", "&lt;italic word=\"plov\"&gt;My favourite food is plov.&lt;/italic&gt; \u2014 an italic tag with the word attribute naming which part to slant"], ans: 0, why: "Wrap ONLY the word you want styled. <i>plov</i> inside the paragraph. The browser doesn\u2019t auto-italic food words. <italic> isn\u2019t a real tag. Italicising the whole sentence changes the meaning.", bloom: "apply" },
    { q: "You want to highlight the word \u201cFriday\u201d in a paragraph about the exam. Which line fits?", opts: ["Just write Friday in UPPERCASE so it stands out in the middle of the sentence without any tags needed for highlighting", "&lt;p&gt;The exam is on &lt;mark&gt;Friday&lt;/mark&gt;.&lt;/p&gt; \u2014 the mark tag gives Friday a yellow background", "&lt;p&gt;The exam is on &lt;b&gt;Friday&lt;/b&gt;.&lt;/p&gt; \u2014 only bold will highlight the word Friday with a yellow background for the reader", "&lt;p&gt;The exam is on FRIDAY.&lt;/p&gt; written in caps is the proper HTML way to give Friday a yellow highlight effect"], ans: 1, why: "<mark> is the highlighter tag \u2014 yellow background. UPPERCASE just makes letters bigger, no highlight. Bold doesn\u2019t add a background. Use <mark> for a yellow highlighter effect.", bloom: "apply" },
    { q: "You want the phone number in your contact section to be slightly smaller, like \u201cfine print.\u201d Which tag?", opts: ["&lt;tiny&gt; \u2014 a simple tag that shrinks any text to a smaller print size compared to the rest of the paragraph", "&lt;small&gt; \u2014 makes text smaller than normal, good for fine print like legal notices or extra details", "&lt;fine&gt; \u2014 the modern HTML5 tag used specifically for shrinking text like legal notes or the fine print at the bottom", "&lt;sub&gt; \u2014 shrinks the text and moves it slightly below the baseline, which gives the correct small fine-print effect"], ans: 1, why: "<small> makes text smaller \u2014 perfect for fine print, legal notes, disclaimers. <tiny> and <fine> aren\u2019t real HTML. <sub> also shrinks but drops the text below the line (used for chemical formulas like H\u2082O).", bloom: "apply" },
    { q: "A student writes <code>&lt;b&gt;&lt;i&gt;Welcome!&lt;/b&gt;&lt;/i&gt;</code> and the page looks broken. What\u2019s wrong?", opts: ["You can\u2019t combine bold and italic in HTML at all, so the page is broken and the student must pick just one tag here", "The tags are closed in the WRONG order \u2014 last opened should be first closed, so it should be &lt;/i&gt;&lt;/b&gt;", "The student used lowercase instead of uppercase b and i, so the browser did not recognise either of the tags today", "Bold and italic tags are old and no longer work in Chrome, so the student should switch to strong and em instead right now"], ans: 1, why: "Nested tags must close in reverse order. Open <b><i>, close </i></b> \u2014 last opened first closed. The student wrote </b></i>, which crosses the tags. Easy fix: swap the closing order.", bloom: "analyze" },
    { q: "Your friend says: \u201cUnderline (<code>&lt;u&gt;</code>) is great for making important words stand out.\u201d Evaluate.", opts: ["Correct \u2014 underline is the most eye-catching way to draw attention to key words, and is used on every modern website today by default", "Correct \u2014 underlined text is always the best choice for highlighting, even better than bold or a yellow background for importance in all cases", "Not a great idea \u2014 on the web, underline usually means link, so users try to click; use &lt;b&gt; or &lt;mark&gt; instead", "Correct \u2014 the underline tag automatically adds click behaviour too, which makes important words become clickable for free on every page always"], ans: 2, why: "For 30 years, underlined text on the web has meant \"link.\" Using <u> for emphasis confuses users \u2014 they try to click and nothing happens. Use <b> for bold, <mark> for highlight, or <em>/<strong> for emphasis.", bloom: "evaluate" },
    { q: "Design a paragraph for a school page: your full name in bold, the word \u201cAmity\u201d in italic, and \u201cFriday\u201d highlighted.", opts: ["Use ALL CAPS for the three words and no tags at all, because caps alone give enough emphasis in a paragraph this short on any page", "Just type the paragraph plainly and hope the reader notices the three important words on their own without any formatting being added", "&lt;p&gt;&lt;b&gt;Name&lt;/b&gt; studies at &lt;i&gt;Amity&lt;/i&gt;. Exam on &lt;mark&gt;Friday&lt;/mark&gt;.&lt;/p&gt;", "Put the entire paragraph inside &lt;b&gt;&lt;i&gt;&lt;mark&gt; tags to make everything in the sentence stand out equally to the reader of this page"], ans: 2, why: "One role, one tag: <b> for the bold name, <i> for the italic school name, <mark> for the highlighted day. Wrapping the whole paragraph in all three would bold-italic-highlight every word \u2014 nothing stands out.", bloom: "create" },
  ],

  // ─── Topic 7: HTML Tables ───
  7: [
    { q: "Which tag starts a table in HTML?", opts: ["&lt;grid&gt; \u2014 a tag used specifically for showing any data arranged in neat rows and columns on a web page", "&lt;spreadsheet&gt; \u2014 a tag that works just like an Excel table, with rows and columns and bold heading cells", "&lt;table&gt; \u2014 the outer wrapper tag that holds all the rows and cells inside it", "&lt;rows&gt; \u2014 the tag for a multi-row data structure, which shows a table-like grid on the web page"], ans: 2, why: "Tables start with <table>. The rows go inside with <tr>, and the cells go inside those with <td> or <th>. <grid>, <spreadsheet>, <rows> aren\u2019t real HTML tags.", bloom: "remember" },
    { q: "What does the <code>&lt;tr&gt;</code> tag mean?", opts: ["Table Row \u2014 creates one horizontal row inside a table, which holds all the cells going across that row", "Top Row \u2014 a special tag for the very first bold row at the top of any table, used just once at the top", "Table Rule \u2014 a tag that draws a thin horizontal rule between the cells of the table on the finished page", "Typography Row \u2014 a styling tag specifically for changing the font in just one horizontal row of the table"], ans: 0, why: "<tr> = Table Row. One <tr> = one horizontal row. Cells (<td> or <th>) go inside. \u201cTop Row,\u201d \u201cTable Rule,\u201d \u201cTypography Row\u201d are made up.", bloom: "remember" },
    { q: "Why does a table need <code>&lt;tr&gt;</code> between <code>&lt;table&gt;</code> and <code>&lt;td&gt;</code>?", opts: ["It’s a pointless extra wrapper that old browsers required, and modern pages don’t need any tr tags anymore at all", "Because every tag in HTML needs exactly three layers of nesting, which is just a core rule of the HTML language everywhere", "Because &lt;td&gt; tags cannot be placed directly inside a file, so they always need another tag wrapping them in every case", "Because the &lt;tr&gt; groups cells into rows — without it, the browser doesn’t know which cells belong together"], ans: 3, why: "Cells need to be grouped into rows. <tr> is the group. Without it, cells would just be floating in the table with no row structure, and the grid would break. Rule: <table> \u2192 <tr> \u2192 <td>.", bloom: "understand" },
    { q: "What\u2019s the difference between <code>&lt;th&gt;</code> and <code>&lt;td&gt;</code>?", opts: ["&lt;th&gt; and &lt;td&gt; are the same tag with two different names, and developers pick one based on personal preference only", "&lt;th&gt; is a header cell (bold by default); &lt;td&gt; is a regular data cell (normal text)", "&lt;th&gt; is used in the top half of the table and &lt;td&gt; is used in the bottom half as a rule for long data tables", "&lt;th&gt; adds a yellow highlight to the cell and &lt;td&gt; adds a grey border, which are the only visual differences"], ans: 1, why: "<th> = table header (bold and centred by default, used in the top row for column names). <td> = table data (regular cell). Use <th> for \u201cName,\u201d \u201cPrice,\u201d \u201cDay.\u201d Use <td> for the actual numbers and words.", bloom: "understand" },
    { q: "You want a 2-column table with headings \u201cDish\u201d and \u201cPrice\u201d and one row of data (Plov, 35000). Which is right?", opts: ["&lt;table&gt; with two rows, each holding one Dish cell and one Price cell \u2014 but with no th tags for the headings at all on top", "A &lt;table&gt; with one &lt;tr&gt; of &lt;th&gt; headings and a second &lt;tr&gt; of &lt;td&gt; data", "&lt;td&gt;Dish, Price&lt;/td&gt;&lt;td&gt;Plov, 35000&lt;/td&gt; with no table or tr tags wrapping them \u2014 browsers figure out the rest of the grid automatically for you", "A list with &lt;li&gt;Dish \u2014 Price&lt;/li&gt;&lt;li&gt;Plov \u2014 35000&lt;/li&gt; because data with two columns is best shown as a simple list without the use of table tags"], ans: 1, why: "Proper nesting: <table> \u2192 <tr> \u2192 <th>/<td>. First row has <th> for headings, second row has <td> for the data. Lists aren't the right shape for two-column data.", bloom: "apply" },
    { q: "Your table\u2019s data shows up but there are no lines between the cells. What\u2019s missing?", opts: ["You forgot the &lt;tr&gt; tags, so the browser is confused about where the rows end and the cells begin on the finished page", "The &lt;table&gt; tag is missing the border attribute \u2014 add border=\"1\" to make the grid lines appear", "Tables never have borders by default and the only way to add lines is to draw each line manually as a separate tag", "The cells are missing their content, so the browser is not showing the grid until every cell has at least one character"], ans: 1, why: "Without border=\"1\", tables render with no visible grid. The data is there, but users see blank space. <table border=\"1\"> shows lines around every cell. Missing <tr> is a different problem (broken layout, not invisible lines).", bloom: "apply" },
    { q: "You\u2019re making a weekly class schedule for your page: Monday\u2013Friday as rows, class times as columns. Which tool fits?", opts: ["A table \u2014 schedule data has real rows (days) and columns (times), so a table is exactly the right shape for it", "A bulleted list with one item per day \u2014 because timetables are easy to read as a simple list of days and their classes", "A long paragraph listing every day and every time in one big block of text \u2014 just natural English without any tags at all", "Several heading tags in sequence \u2014 h1 for each day and h2 for each time slot \u2014 so the schedule looks structured on the page"], ans: 0, why: "A schedule is real tabular data \u2014 days are rows, time slots are columns. Tables are built for exactly this. Lists and paragraphs don\u2019t show the row/column structure, and headings are for titles, not data.", bloom: "apply" },
    { q: "A student wrote &lt;table&gt;&lt;td&gt;Plov&lt;/td&gt;&lt;td&gt;35000&lt;/td&gt;&lt;/table&gt; and the table looks broken. What\u2019s wrong?", opts: ["The student forgot the border=\"1\" attribute, so the cells appear broken on every modern browser by default settings", "The closing &lt;/table&gt; tag must be before the data cells, not after them, or the browser refuses to render the table", "The cells should use &lt;th&gt; because the data is only two things and there are no extra rows shown on the page today", "The &lt;td&gt; cells are directly inside &lt;table&gt; with no &lt;tr&gt; around them — cells must be inside a row"], ans: 3, why: "The rule is <table> \u2192 <tr> \u2192 <td>. Putting <td> straight inside <table> skips the row layer and breaks the structure. Wrap the cells in <tr>...</tr> and the table will render correctly.", bloom: "analyze" },
    { q: "A friend says: \u201cI\u2019ll use a table to lay out the whole page \u2014 header on top, menu on the left, content on the right.\u201d Evaluate.", opts: ["Correct \u2014 tables are the proper way to lay out every modern web page, and all the big sites you know use them today", "Correct \u2014 tables are faster than any other layout method, which is why every professional site still uses them for page layout", "Not a great idea \u2014 tables are for DATA with real rows and columns; whole-page layout should use CSS instead today", "Correct \u2014 using tables for layout makes the page look the same on every screen size automatically, no work needed", ], ans: 2, why: "Tables are for tabular data \u2014 menus, schedules, prices. For page LAYOUT (header/menu/content), modern sites use CSS. Layout tables break on phones (no reflow) and confuse screen readers. Right tool for the right job.", bloom: "evaluate" },
    { q: "Design a simple 3-row table for a Tashkent bakery\u2019s menu (Dish / Price), with 2 menu items.", opts: ["&lt;table border=\"1\"&gt; with a header row of &lt;th&gt; and two data rows of &lt;td&gt; for Samsa 8000 and Non 5000", "Two paragraphs: &lt;p&gt;Samsa 8000&lt;/p&gt; &lt;p&gt;Non 5000&lt;/p&gt; \u2014 this is simpler and does not need any table tags around it at all", "An image of a photo of the menu board \u2014 there is no real need to write the menu in HTML when a photo works just fine on the page", "&lt;table&gt;Samsa 8000 Non 5000&lt;/table&gt; \u2014 just write all the text inside the table tag and let the browser arrange the text neatly for you"], ans: 0, why: "A proper 3-row table: <table border=\"1\"><tr><th>Dish</th><th>Price</th></tr><tr><td>Samsa</td><td>8000</td></tr><tr><td>Non</td><td>5000</td></tr></table>. Plain paragraphs lose the column alignment. Photo of a menu isn't HTML. Just text inside <table> has no structure.", bloom: "create" },
  ],

  // ─── Topic 8: HTML Lists ───
  8: [
    { q: "Which tag creates a numbered (ordered) list?", opts: ["&lt;ul&gt; — the unordered list tag, which automatically numbers each item inside it on the finished web page", "&lt;list order=\"yes\"&gt; — a list tag with an order attribute that turns it into a numbered list when set to yes", "&lt;numbers&gt; — the simple descriptive tag used for lists that should display in a neat numbered order on the web page", "&lt;ol&gt; — short for ordered list, which adds numbers like 1, 2, 3 before each item"], ans: 3, why: "<ol> = ordered list. It automatically numbers items. <ul> is unordered (bullets). <list> and <numbers> aren\u2019t real HTML tags.", bloom: "remember" },
    { q: "What tag is used for each item inside a list?", opts: ["&lt;item&gt; \u2014 a simple descriptive tag used inside both ordered and unordered lists for every individual line of content", "&lt;li&gt; \u2014 list item, used inside both &lt;ul&gt; and &lt;ol&gt;", "&lt;point&gt; \u2014 the natural tag for a bullet point, which works inside any list type including ordered and unordered lists", "&lt;entry&gt; \u2014 a tag that represents one entry of the list and works inside any list element you put around it on a page"], ans: 1, why: "<li> = list item. The same <li> tag is used inside both <ul> and <ol>. The wrapper changes the look (bullets vs numbers), but the item tag stays the same. <item>, <point>, <entry> aren\u2019t real.", bloom: "remember" },
    { q: "Why would you use <code>&lt;ol&gt;</code> for cooking steps but <code>&lt;ul&gt;</code> for a shopping list?", opts: ["&lt;ol&gt; and &lt;ul&gt; do the same thing and the choice is just a matter of personal taste of the page author always", "Ordered and unordered list tags were invented by different companies, and sites pick whichever matches their logo colour", "&lt;ol&gt; is for long lists and &lt;ul&gt; is only for short lists of five items or fewer on the same page", "Cooking steps must be followed in order (step 2 after step 1), but shopping items can be bought in any order"], ans: 3, why: "<ol> = order matters (step 1, step 2, step 3). <ul> = order doesn\u2019t matter (bread, milk, eggs \u2014 same result either way). Match the tag to the meaning.", bloom: "understand" },
    { q: "What actually changes when you swap <code>&lt;ol&gt;</code> for <code>&lt;ul&gt;</code>?", opts: ["The numbers or bullets change \u2014 ol gives numbers, ul gives bullets. The &lt;li&gt; items themselves stay the same", "All the list items completely disappear from the page, because the browser cannot handle the switch between the two tags", "The text size of every list item inside becomes smaller, because ul uses smaller font by default compared to ol tags", "Every word inside the list becomes bold automatically, because ul is designed to emphasise each entry inside it on page"], ans: 0, why: "Only the outer wrapper changes the marker: <ol> = numbers, <ul> = bullets. The <li> items don\u2019t change. Same items, different markers. No text size or weight changes happen.", bloom: "understand" },
    { q: "You want a list of 3 things you do every morning, in order. Which lines fit?", opts: ["&lt;ol&gt;&lt;li&gt;Wake up&lt;/li&gt;&lt;li&gt;Brush teeth&lt;/li&gt;&lt;li&gt;Eat breakfast&lt;/li&gt;&lt;/ol&gt; \u2014 ordered list with three li items", "&lt;ul&gt;&lt;li&gt;Wake up&lt;/li&gt;&lt;li&gt;Brush teeth&lt;/li&gt;&lt;li&gt;Eat breakfast&lt;/li&gt;&lt;/ul&gt; \u2014 a bulleted unordered list, even though the order of the steps actually matters in this task", "&lt;p&gt;1. Wake up 2. Brush teeth 3. Eat breakfast&lt;/p&gt; as a single paragraph with the step numbers typed out by hand directly", "&lt;steps&gt;Wake up, Brush teeth, Eat breakfast&lt;/steps&gt; is the simplest tag for a list of numbered steps on a web page"], ans: 0, why: "Morning routine has a clear order \u2014 use <ol>. Each step is its own <li>. A <ul> would give bullets (misleading here). Typing numbers by hand in a <p> misses the meaning. <steps> isn\u2019t a real tag.", bloom: "apply" },
    { q: "You want to list your 4 favourite foods in any order. Which lines fit?", opts: ["&lt;ol&gt;&lt;li&gt;Plov&lt;/li&gt;&lt;li&gt;Samsa&lt;/li&gt;&lt;li&gt;Lagman&lt;/li&gt;&lt;li&gt;Manti&lt;/li&gt;&lt;/ol&gt; \u2014 ordered because your favourites should be ranked from best to worst", "&lt;ul&gt;&lt;li&gt;Plov&lt;/li&gt;&lt;li&gt;Samsa&lt;/li&gt;&lt;li&gt;Lagman&lt;/li&gt;&lt;li&gt;Manti&lt;/li&gt;&lt;/ul&gt; \u2014 unordered, bullets", "&lt;favourites&gt;Plov Samsa Lagman Manti&lt;/favourites&gt; \u2014 a special favourites tag that lists every item in a row neatly", "&lt;p&gt;Plov\\nSamsa\\nLagman\\nManti&lt;/p&gt; with newline characters inside the paragraph will give a properly bulleted list automatically"], ans: 1, why: "Favourites in no particular order \u2014 use <ul>. If you actually want to rank them 1-4, use <ol>. <favourites> isn\u2019t a real tag. Newlines in a <p> don\u2019t make a list \u2014 browsers ignore raw newlines.", bloom: "apply" },
    { q: "You want a list of your top 3 films, numbered from favourite to least favourite. Which is right?", opts: ["&lt;ol&gt; with three &lt;li&gt; items, because ordered list gives numbers 1 to 3 automatically for rankings like this one", "&lt;ul&gt; with three &lt;li&gt; items, since favourites are usually shown with bullets even when the ranking is important to you", "A table with a ranking column that adds the numbers 1, 2, 3 manually in each row \u2014 which is longer and harder to maintain", "A set of heading tags &lt;h1&gt; for each film \u2014 because headings can show the ranking by their size, biggest for favourite"], ans: 0, why: "Ranking = ordered list. <ol> numbers the items automatically (1, 2, 3). <ul> gives bullets, which hides the ranking. A table works but is more effort. Headings are for titles, not rankings.", bloom: "apply" },
    { q: "A student writes &lt;ul&gt;Plov&lt;/ul&gt;&lt;ul&gt;Samsa&lt;/ul&gt; and the page shows two bullets but the items look weird. What\u2019s wrong?", opts: ["The student needs to add border=\"1\" to the ul tags for the bullets to display correctly in a modern browser like Chrome", "The student forgot to put each item in &lt;li&gt; tags \u2014 the items should be &lt;li&gt;Plov&lt;/li&gt; inside one ul", "The student needs to use &lt;ol&gt; for food names, since food items are always shown as an ordered list in modern HTML", "The student is typing the items outside the tags, and ul only works when every single word is wrapped in two or more tags"], ans: 1, why: "Each item needs <li>. The correct structure is ONE <ul> with multiple <li> inside: <ul><li>Plov</li><li>Samsa</li></ul>. The student also used a new <ul> for every item, which isn\u2019t needed.", bloom: "analyze" },
    { q: "Your classmate says: \u201cNumbered lists are fancier, so I always use &lt;ol&gt; even for my shopping list.\u201d Evaluate.", opts: ["Correct \u2014 ordered lists make pages look cleaner and professional, so you should use them everywhere you can by default on any page", "Correct \u2014 ordered lists load faster than unordered lists on every browser, so using &lt;ol&gt; always is the better choice for any kind of list", "Not quite \u2014 numbers suggest order matters, so &lt;ol&gt; is misleading for any-order lists; &lt;ul&gt; is right", "Correct \u2014 ordered and unordered lists render identically on modern phones, so the choice doesn\u2019t make any real difference to a visitor today"], ans: 2, why: "Numbers imply sequence. Using <ol> for a list where order doesn't matter (shopping, hobbies) is misleading \u2014 readers think item 1 is first for a reason. Pick the tag that matches the meaning of your list.", bloom: "evaluate" },
    { q: "Design the lists for a plov recipe page: ingredients (any order) and cooking steps (strict order).", opts: ["Everything in one huge ordered list with both ingredients and steps mixed together so every line has a number on the left edge", "Everything in one bulleted list so the whole recipe uses bullet points only and nothing is numbered on the finished page in any place", "&lt;ul&gt; for ingredients and &lt;ol&gt; for steps \u2014 one list per role", "A long paragraph with commas separating every ingredient and every step, because lists are not really needed on a page of any kind"], ans: 2, why: "Match the list to the meaning: ingredients can be added in any order (<ul>, bullets), cooking steps must follow order (<ol>, numbers). Two separate lists, each using the right wrapper.", bloom: "create" },
  ],

  // ─── Topic 9: Hyperlinks ───
  9: [
    { q: "Which tag creates a hyperlink?", opts: ["&lt;link&gt; — the most intuitive tag name, which creates a clickable link to any web page address you put inside it", "&lt;click&gt; — the tag used in modern HTML5 specifically for any clickable element placed inside the page body section", "&lt;url&gt; — a tag that takes a web address and automatically displays it as a clickable link on the finished page", "&lt;a&gt; — the anchor tag, used with the href attribute to link to another page or website"], ans: 3, why: "The anchor tag is <a>, short for anchor. It takes the href attribute for the destination. <link> is a real tag but it lives in <head> (for stylesheets). <url> and <click> aren\u2019t real HTML tags.", bloom: "remember" },
    { q: "Which attribute sets WHERE a link goes?", opts: ["src \u2014 the source attribute, used for both images and links to point at the file or URL they should load when clicked", "href \u2014 short for hypertext reference, holds the URL the user jumps to when they click the link", "go \u2014 a short and simple attribute name that tells the browser where to send the user after they click the link on page", "link \u2014 a common-sense attribute name that holds the URL the link points to, used inside every anchor tag on every page"], ans: 1, why: "href = hypertext reference. <a href=\"https://yandex.uz\">Search</a>. The attribute is href, not src (which is for images), not go or link (which aren\u2019t real attributes).", bloom: "remember" },
    { q: "Why do we use <code>target=\"_blank\"</code> on some links?", opts: ["It opens the link in a new browser tab, so the current page stays open while the user visits the other site", "It makes the link underline itself, because without target blank all links would appear as plain text on the page", "It tells the search engine the link is important, which makes the site rank much higher on Google search results", "It changes the link colour to blue so users can clearly tell that it is a clickable link on the finished web page"], ans: 0, why: "target=\"_blank\" opens the link in a new tab. Your page stays open in the original tab. Used often for external links \u2014 users don\u2019t lose your site. Underline and colour come from CSS, not this attribute.", bloom: "understand" },
    { q: "Why do we say the <code>&lt;a&gt;</code> tag makes the web \u201ca web\u201d?", opts: ["Because the letter a comes first in the alphabet, and links were invented before any other HTML element was made", "Because &lt;a&gt; is actually short for \u201carachnid,\u201d which is a spider, which naturally builds its web out of many threads", "Because links connect pages to other pages, creating a net of connections \u2014 without links, every page would be a dead end", "Because the &lt;a&gt; tag automatically adds a spider-web background image to every page that uses links in this way"], ans: 2, why: "The \u201cweb\u201d in WWW is a web of connected pages. Hyperlinks are the connections. Without <a>, every page would be isolated. That\u2019s why the anchor tag is considered the backbone of the web.", bloom: "understand" },
    { q: "You want a link that says \u201cVisit Amity\u201d and goes to <code>https://amity.edu</code>. Which line is right?", opts: ["&lt;a url=\"https://amity.edu\" text=\"Visit Amity\"&gt; — a cleaner modern version of the anchor tag using url and text attributes", "&lt;a&gt;https://amity.edu&lt;/a&gt; — put the URL as the text, because browsers auto-detect URLs inside anchor tags in every case", "&lt;link to=\"https://amity.edu\"&gt;Visit Amity&lt;/link&gt; — a link tag with a to attribute, which works on every modern web browser today", "&lt;a href=\"https://amity.edu\"&gt;Visit Amity&lt;/a&gt; — anchor tag with the href attribute and the visible text Visit Amity"], ans: 3, why: "Standard link: <a href=\"URL\">visible text</a>. The attribute is href. The visible words go between the tags, not as another attribute. <link to=\"\"> isn\u2019t how links are written.", bloom: "apply" },
    { q: "You want a link to open in a NEW tab so the user keeps your page open. Which line is right?", opts: ["&lt;a href=\"https://uzum.uz\" target=\"_blank\"&gt;Uzum&lt;/a&gt; \u2014 add target=\"_blank\" inside the opening anchor tag", "&lt;a href=\"https://uzum.uz\" new=\"tab\"&gt;Uzum&lt;/a&gt; \u2014 the new attribute tells the browser to open the link in a new tab", "&lt;a href=\"https://uzum.uz\"&gt;Uzum&lt;/a&gt;&lt;newtab&gt; \u2014 add a newtab tag right after the anchor to open the link in a new tab", "&lt;a href=\"https://uzum.uz\" window=\"open\"&gt;Uzum&lt;/a&gt; \u2014 the window attribute opens the link in a new browser window instead"], ans: 0, why: "target=\"_blank\" is the standard \u201copen in new tab\u201d attribute. new, <newtab>, and window aren\u2019t real HTML. Remember the exact spelling: target=\"_blank\" with an underscore.", bloom: "apply" },
    { q: "You want a link that jumps to another page on YOUR own site (<code>about.html</code>, in the same folder). Which is right?", opts: ["&lt;a href=\"about.html\"&gt;About me&lt;/a&gt; \u2014 a simple relative link to a file in the same folder as the current page", "&lt;a href=\"https://about.html\"&gt;About me&lt;/a&gt; \u2014 always start with https:// even for files in your own local folder, no matter what", "&lt;a href=\"C:/Users/me/about.html\"&gt;About me&lt;/a&gt; \u2014 use the full Windows path so the browser can find the file on your machine", "&lt;a href=\"local:about.html\"&gt;About me&lt;/a&gt; \u2014 the local: prefix tells the browser to load a file from the same folder"], ans: 0, why: "For files in the same folder, just use the file name: href=\"about.html\". Full URLs (https://) are for external sites. Windows paths only work on your computer, not for anyone else. local: isn\u2019t a real scheme.", bloom: "apply" },
    { q: "A classmate\u2019s link says \u201cClick here\u201d and goes nowhere. When clicked, nothing happens. What\u2019s the most likely mistake?", opts: ["The link text \u201cClick here\u201d is wrong \u2014 browsers refuse to load pages whenever the link text contains the word here in it", "The student used &lt;a&gt; without an href attribute \u2014 no href means the link has no destination and so nothing happens", "The browser needs to be restarted whenever a link is clicked, which resets the entire page back to its default state for all", "The student needs to open Notepad in administrator mode, since regular Notepad cannot save links that actually work"], ans: 1, why: "A link needs href. Without it, <a>Click here</a> renders as text but has nothing to click to. Add href=\"...\" and point it somewhere. Also tip: use better words than \u201cclick here\u201d \u2014 tell the user where the link goes.", bloom: "analyze" },
    { q: "A friend says: \u201cEvery link on my page should open in a new tab \u2014 it keeps users on my site.\u201d Evaluate.", opts: ["Correct \u2014 all links should open new tabs, because users always prefer having more tabs open at any given time of the day", "Not a great idea \u2014 internal links (same site) should open in the same tab; new tabs are for external sites only", "Correct \u2014 target=\"_blank\" on every link makes the site rank higher on Google, so always add it everywhere you can", "Correct \u2014 the browser\u2019s Back button does not work if links open in the same tab, so always use target=\"_blank\" for safety"], ans: 1, why: "Internal links (same site pages) should open in the SAME tab \u2014 users expect that. target=\"_blank\" is for EXTERNAL links so the user doesn\u2019t lose your page. Putting it on every link clogs the tab bar and confuses people.", bloom: "evaluate" },
    { q: "Design the links for a small Tashkent bakery\u2019s home page: \u201cMenu\u201d, \u201cContact\u201d, and a link to Yandex Maps for directions.", opts: ["Three links that all use target=\"_blank\" because every click should always open in a new tab for the user to see on the page, no matter where the link actually leads to", "Only one single link that says \u201cClick here\u201d and goes to Google, because users can search for everything themselves from that page without needing any other links at all from the bakery", "Internal &lt;a&gt; links for Menu and Contact (same tab) + an external Yandex Maps link using target=\"_blank\" for a new tab", "One long paragraph listing every link as plain text like yandex.uz/maps and contact.html \u2014 the browser makes them clickable on its own without any tags ever being needed here"], ans: 2, why: "Internal links (Menu, Contact) use the same tab. The external Maps link uses target=\"_blank\" so the bakery's page stays open. Each link has descriptive text \u2014 never \"click here.\" Plain text URLs don't become clickable by themselves.", bloom: "create" },
  ],

  // ─── Topic 10: Images & Image Links ───
  10: [
    { q: "Which tag displays an image on a web page?", opts: ["&lt;picture&gt; \u2014 the intuitive descriptive tag name used for showing pictures of any type on modern HTML web pages today", "&lt;photo&gt; \u2014 the tag used specifically for displaying JPG and PNG photo files on every kind of modern web page", "&lt;img&gt; \u2014 the image tag, which is self-closing and uses the src attribute to point to the image file", "&lt;image src=\"file.jpg\"&gt; \u2014 the long form tag name, which is the modern HTML5 version that all new browsers accept as standard"], ans: 2, why: "The image tag is <img>. It\u2019s self-closing \u2014 no </img> needed. All info goes in attributes (src, alt, width). <picture> is a real tag but it\u2019s for responsive images (advanced). <photo> and <image> aren\u2019t standard.", bloom: "remember" },
    { q: "Which attribute holds the image file name?", opts: ["file — the obvious descriptive attribute name, which tells the browser which image file to load on the page", "filename — the full descriptive attribute name used for pointing at an image file in the correct folder on the web server", "name — the attribute that stores the name of the file so the browser can find and display the correct image on the page", "src — short for source, the path or URL to the image file"], ans: 3, why: "src = source. Holds the path or URL of the image. <img src=\"cat.jpg\"> or <img src=\"https://site.uz/logo.png\">. file, name, filename aren\u2019t real image attributes in HTML.", bloom: "remember" },
    { q: "Why is <code>&lt;img&gt;</code> self-closing (no <code>&lt;/img&gt;</code>)?", opts: ["It’s an old historical accident that every browser has simply copied since the 1990s for no real good reason at all", "Because the closing tag is only needed for text elements and the image tag doesn’t contain any text inside it at all", "Because HTML decided self-closing tags should be random — img just happened to be one of the lucky ones chosen", "Because the image tag has no content between tags — all its info is in attributes, so there’s nothing to wrap"], ans: 3, why: "Self-closing tags have no content between tags \u2014 all their info fits in attributes. <img src=\"cat.jpg\" alt=\"...\"> carries everything inside the single tag. Same for <br> and <hr>.", bloom: "understand" },
    { q: "Why is the <code>alt</code> attribute important for images, even if the image loads fine?", opts: ["It makes the image appear with a nice rounded border around it, which is why designers add alt to every single image on pages", "It\u2019s read aloud by screen readers for blind users and helps search engines understand what the image shows", "It speeds up the page loading because the browser can skip loading the image itself whenever alt text is written in the tag", "It adds a tooltip that only appears when the user clicks and holds on the image for exactly three seconds or more"], ans: 1, why: "alt has two jobs: backup text if the image fails, AND spoken description for blind users using screen readers. Search engines also use it to index what\u2019s in the image. Small attribute, big accessibility win.", bloom: "understand" },
    { q: "You want to show a photo of Registan Square, 300 pixels wide, with backup text. Which line is right?", opts: ["&lt;img src=\"registan.jpg\" width=\"300\" alt=\"Registan Square\"&gt; \u2014 all three attributes in one self-closing img tag", "&lt;img&gt;registan.jpg, 300, Registan Square&lt;/img&gt; \u2014 put file, width, and alt as comma-separated text between the tags", "&lt;photo src=\"registan.jpg\" size=\"300\"&gt; Registan Square &lt;/photo&gt; \u2014 the photo tag with descriptive attributes and text content", "&lt;image&gt; &lt;src&gt;registan.jpg&lt;/src&gt; &lt;width&gt;300&lt;/width&gt; &lt;alt&gt;Registan Square&lt;/alt&gt; &lt;/image&gt; \u2014 nested child tags"], ans: 0, why: "All attributes inside one <img> tag. No content between tags because <img> is self-closing. <photo> and <image> aren\u2019t real tags. Attributes are never nested as child tags.", bloom: "apply" },
    { q: "You want to make the Amity logo clickable, so clicking it goes to <code>https://amity.edu</code>. Which is right?", opts: ["Add href=\"https://amity.edu\" to the img tag: &lt;img src=\"logo.png\" href=\"https://amity.edu\"&gt; \u2014 img supports href directly", "Wrap the img inside an anchor tag: &lt;a href=\"https://amity.edu\"&gt;&lt;img src=\"logo.png\" alt=\"Amity\"&gt;&lt;/a&gt;", "Use an onclick attribute: &lt;img src=\"logo.png\" onclick=\"https://amity.edu\"&gt; \u2014 onclick takes the URL to go to on click", "Place the img tag and the anchor tag side by side in the same row so the browser automatically links them together on load"], ans: 1, why: "To make an image clickable, wrap <img> inside <a>. The <a> carries the href. <img> doesn\u2019t take href directly. onclick is a JavaScript thing, not the simple HTML way. Just wrap it: <a href=\"url\"><img ...></a>.", bloom: "apply" },
    { q: "You want a 200-pixel-wide photo of Chorsu Bazaar on your page, with \u201cChorsu Bazaar\u201d as the backup text. Which is right?", opts: ["&lt;img src=\"chorsu.jpg\" width=\"200\" alt=\"Chorsu Bazaar\"&gt; \u2014 src for the file, width for the pixel size, alt for the backup text", "&lt;img&gt; \u2014 just the empty image tag, since the browser guesses the correct photo from the nearby paragraph text on the page", "&lt;photo file=\"chorsu.jpg\" size=\"200\" backup=\"Chorsu Bazaar\"&gt; \u2014 a photo tag with descriptive attribute names instead of the img defaults", "&lt;img&gt;chorsu.jpg 200 Chorsu Bazaar&lt;/img&gt; \u2014 put file, size, and backup text between the tags as space-separated values"], ans: 0, why: "Three attributes inside <img>: src, width, alt. The browser can\u2019t guess which image to show. <photo> isn\u2019t a tag, and the real attribute names are src/width/alt (not file/size/backup).", bloom: "apply" },
    { q: "A student\u2019s image shows a broken-icon and no alt text appears either. What\u2019s the most likely reason?", opts: ["The image file is fine, but the browser is too old to handle any image tags written in lowercase letters on modern pages", "The student used width=\"200\" which broke the tag — removing the width attribute will make the image show correctly again", "The src points to a file that doesn’t exist AND the alt attribute is missing — so no photo and no backup text appear", "The page needs to be saved as .png instead of .html, because image-heavy pages require a different file extension to work"], ans: 2, why: "Broken icon = src file missing. No text next to it = no alt attribute. Fix both: correct the src path (check the filename) AND add alt=\"a description\". Always include alt \u2014 so when images fail, users at least know what was meant to be there.", bloom: "analyze" },
    { q: "Your friend says: \u201cI put my 10-megapixel photos straight on the page. Why wait to resize?\u201d Evaluate.", opts: ["Correct \u2014 bigger photos make pages look more professional, so always use the largest file size you can on every page you build for them", "Not a great idea \u2014 huge photos slow pages on mobile data; resize them first", "Correct \u2014 modern browsers automatically resize photos without any slowdown, so the file size on the server does not matter at all for visitors", "Correct \u2014 Chrome has a feature that shrinks all big images to 300 pixels, so you can safely upload any size photo you have to a page today"], ans: 1, why: "Browsers download the full-size image before showing it. A 10MB photo takes seconds on mobile data. Resize photos to the actual display width (say 600 pixels) before uploading. Small thing, huge speed win.", bloom: "evaluate" },
    { q: "Design the image markup for a simple Tashkent travel page with a clickable photo of Registan Square that links to a Wikipedia page.", opts: ["&lt;a href=\"https://en.wikipedia.org/wiki/Registan\"&gt;&lt;img src=\"registan.jpg\" alt=\"Registan Square in Samarkand\" width=\"400\"&gt;&lt;/a&gt;", "Just an img tag with no anchor tag and no alt: &lt;img src=\"registan.jpg\" width=\"400\"&gt; because alt is optional and photos work fine on their own", "Two separate elements: an img tag followed by a regular text link that says \u201cRead more\u201d on the line directly below the photo image", "An anchor tag on its own with the URL and the photo name as plain text content: &lt;a href=\"wiki.org/Registan\"&gt;registan.jpg&lt;/a&gt;"], ans: 0, why: "Wrap <img> inside <a>. The <img> has src (file), alt (accessibility), and width (size). The <a> holds the href to Wikipedia. A photo without alt fails accessibility, and a text link alone isn\u2019t a clickable photo.", bloom: "create" },
  ],

  // ─── Topic 11: Build a Full HTML Page ───
  11: [
    { q: "Which line must appear at the very TOP of every modern HTML page?", opts: ["&lt;html5&gt; — the tag that tells the browser this page uses the modern HTML5 standard and not the old HTML4 standard", "&lt;start page&gt; — the first tag on every modern HTML page, which tells the browser the page content is starting now", "&lt;version 5&gt; — the version tag, needed for every modern HTML5 page, which replaces the older XHTML doctype declarations", "&lt;!DOCTYPE html&gt; — tells the browser to use modern HTML5 rules"], ans: 3, why: "Every HTML page starts with <!DOCTYPE html>. This tells the browser to use modern HTML5 rules. <html5>, <version 5>, <start page> aren\u2019t real HTML.", bloom: "remember" },
    { q: "What\u2019s the standard order of the main sections in an HTML page?", opts: ["&lt;body&gt; first for content, then &lt;head&gt; for settings at the bottom, all wrapped in the outer &lt;html&gt; element on the page", "&lt;!DOCTYPE html&gt;, then &lt;html&gt;, with &lt;head&gt; before &lt;body&gt; inside it", "&lt;html&gt; with &lt;head&gt; and &lt;body&gt; as two completely separate blocks side by side, not nested inside the html at all", "&lt;head&gt; first for settings, then the DOCTYPE line, then &lt;html&gt; wrapping only the &lt;body&gt; element at the end"], ans: 1, why: "Correct shape: <!DOCTYPE html> on line 1, then <html> wrapping <head> first (settings, title) and <body> second (visible content). Head before body, always.", bloom: "remember" },
    { q: "Why do we put a COMMENT above each section of a long HTML page?", opts: ["Comments add rounded borders around each section, which makes the final page look more polished when it is finished", "To label sections for humans \u2014 &lt;!-- Menu table --&gt; makes the file easy to scan for you and your teammates", "Comments speed up the page load because the browser can skip sections when it sees a comment marker in the code", "Comments are required by HTML5 rules, and without them the browser refuses to render the sections they are next to"], ans: 1, why: "Section-label comments (<!-- Header -->, <!-- Menu -->) help humans scan long files. No visual effect, no speed change, not required \u2014 just good practice that teachers and teammates love.", bloom: "understand" },
    { q: "Why is matching the right tag to the right job important when you build a full page?", opts: ["Because every tag has a different background colour by default, and mixing them creates a colourful, modern-looking page layout", "Because wrong tags make the page refuse to load on older browsers, so every tag must match its original intended role", "Because the right tag carries the right meaning — a table for data, a list for items, a heading for a title", "Because wrong tags trigger Chrome’s safety warning, which stops users from visiting your finished web page at all"], ans: 2, why: "Tags carry meaning. A <table> tells browsers and screen readers \u201cthis is row/column data.\u201d A <ul> says \u201cthis is a list.\u201d Wrong tags work visually but lose meaning \u2014 bad for accessibility, SEO, and future maintenance.", bloom: "understand" },
    { q: "You\u2019re building an \u201cAbout Me\u201d page with your name, a photo, 3 subjects, 3 hobbies, and a link to your school. Which tags fit best?", opts: ["All the content inside one large &lt;table&gt; with a single cell holding everything, which makes the layout look more organised", "&lt;p&gt; for everything — every item wrapped in a paragraph tag, because a page of paragraphs is cleaner and easier to read", "One giant &lt;h1&gt; that holds the name, the subjects, and the hobbies — then a link tag at the end for the school address", "&lt;h1&gt; for name, &lt;img&gt; for photo, &lt;table&gt; for subjects, &lt;ul&gt; for hobbies, &lt;a&gt; for the school link"], ans: 3, why: "Match tag to role: <h1> for name (main title), <img> for the photo, <table> for subject-grade pairs (rows and columns), <ul> for hobbies (no strict order), <a> for the link. Using one tag for everything loses structure.", bloom: "apply" },
    { q: "You want a simple page for a Tashkent bakery with the shop name, a menu, and opening hours. Which structure fits?", opts: ["&lt;h1&gt; for the shop name, &lt;table&gt; for the menu (Dish and Price), &lt;p&gt; or &lt;ul&gt; for the opening hours list", "Everything inside one &lt;p&gt; paragraph, including the shop name, the menu, and the hours \u2014 because it keeps the code simple", "A set of &lt;h1&gt; tags \u2014 one for the shop name, one for each menu item, and one for each opening hour line on the page", "An &lt;img&gt; of a photo of the menu chalkboard \u2014 no text is needed at all, since a photo tells the customer everything"], ans: 0, why: "<h1> for the shop name. A table is perfect for menu (dish/price rows and columns). Hours list fits in <p> or <ul>. One giant paragraph loses structure. Many <h1> dilutes the main title. A photo of the menu isn\u2019t accessible.", bloom: "apply" },
    { q: "You want your personal page to include a main heading, a paragraph with bold text, a list of 3 hobbies, and a link to Amity. Which set of tags do you need?", opts: ["&lt;h1&gt;, &lt;p&gt; + &lt;b&gt;, &lt;ul&gt; + &lt;li&gt;, and &lt;a href&gt; \u2014 right tool per job", "One &lt;body&gt; tag with everything inside it \u2014 no headings, no lists, no links, because the body alone handles all the page content inside itself", "Only a single &lt;h1&gt; tag containing the heading, the paragraph, the hobbies, and the link, all separated with line breaks inside a single tag together", "A &lt;div&gt; for the whole page, with CSS classes on every word instead of using any real HTML tags at all in the entire file from top to bottom"], ans: 0, why: "Each piece matches a tag: main heading = <h1>, paragraph with formatted text = <p><b>...</b></p>, hobbies list = <ul><li>...</li></ul>, link = <a href=\"...\">...</a>. This is the full-page pattern that earns marks in the exam.", bloom: "apply" },
    { q: "A student\u2019s exam page has a table, a list, and a link, but when it opens in Chrome the table has no lines and one heading stays big on every line. What went wrong?", opts: ["The student used lowercase instead of UPPERCASE tags, so Chrome couldn\u2019t recognise the tags and broke the whole page at once", "Missing border=\"1\" on the &lt;table&gt; AND a missing closing &lt;/h1&gt; somewhere", "The student forgot to add the DOCTYPE line, which prevents Chrome from rendering tables or headings anywhere on the page at all", "The file was saved as .html instead of .txt, so the browser treats the code as plain text and ignores the tag formatting completely"], ans: 1, why: "Two separate bugs. Invisible table = missing border=\"1\" on <table>. Everything-is-heading = missing </h1> close, so the heading never ends. Both are super common beginner mistakes \u2014 fix both and the page renders cleanly.", bloom: "analyze" },
    { q: "A classmate says: \u201cI\u2019ll skip comments and extra structure \u2014 the teacher only cares that my page renders.\u201d Evaluate.", opts: ["Correct \u2014 only the final visual output matters, because teachers mostly grade by looking at the page in Chrome for a minute", "Correct \u2014 comments slow the page down, and extra structure makes the HTML file bigger to download on slow Wi-Fi every time", "Not a great idea \u2014 marks are given for clean structure, correct tags, and comments that show you understand what you built", "Correct \u2014 professional web developers never use comments, so skipping them for the exam is a smart move to save time"], ans: 2, why: "Renders = minimum. Teachers grade on structure, correct tag choice, and evidence of understanding. Comments like <!-- Menu --> show you planned your page. Skipping structure loses easy marks. Looks fine, scores poorly.", bloom: "evaluate" },
    { q: "Design a full HTML page for a Tashkent samsa shop: shop name, a paragraph with one bold word, a menu table, a list of 3 samsa types, and a link to Yandex Maps.", opts: ["Full skeleton + &lt;h1&gt;, &lt;p&gt;&lt;b&gt;, &lt;table border=\"1\"&gt;, &lt;ul&gt;, &lt;a href&gt; \u2014 one tag per role, with section comments", "One enormous &lt;p&gt; paragraph containing all the shop name, the menu, the samsa list, and the Yandex Maps address separated only by simple line breaks in the source file of the web page", "Just a photo of the shop menu board and nothing else \u2014 an &lt;img&gt; alone covers everything a potential customer needs to know about the shop and its menu today", "A set of twenty separate &lt;h1&gt; tags for every word on the page, with no other tags anywhere, because headings handle every kind of content nicely for the viewer"], ans: 0, why: "Full page = full skeleton: <!DOCTYPE html>, <html>, <head><title>, <body>, <h1>, formatted paragraph with <p><b>, <table border=\"1\"> for menu (dish/price), <ul> for samsa types, <a href> for map link. Section comments make it clean. Anything less loses the structure marks.", bloom: "create" },
  ],
};
